import {buildingMaterialPreset,buildingMaterialRecipe,BUILDING_PROFILES,BUILDING_ZONES} from '../city/building-material.js';
import {PRESETS,recipe as hullRecipe} from '../hull/surface.js';
export const GRAPH_SCHEMA='aether.material-graph/1';
export const NODE_TYPES={buildingStage:{label:'Building stage',inputs:[['in','surface']],output:'surface'},building:{label:'Building finish',inputs:[],output:'surface'},hull:{label:'Hull finish',inputs:[],output:'surface'},growth:{label:'Procedural surface',inputs:[],output:'surface'},bitmap:{label:'Imported PBR maps',inputs:[],output:'surface'},urban:{label:'Urban surface',inputs:[],output:'surface'},scan:{label:'Scanned material',inputs:[],output:'surface'},pack:{label:'Published pack',inputs:[],output:'surface'},localPack:{label:'Imported pack',inputs:[],output:'surface'},noise:{label:'Noise mask',inputs:[],output:'mask'},finish:{label:'Finish adjustment',inputs:[['in','surface']],output:'surface'},weather:{label:'Weathering',inputs:[['in','surface']],output:'surface'},blend:{label:'Material blend',inputs:[['base','surface'],['layer','surface'],['mask','mask']],output:'surface'},output:{label:'PBR output',inputs:[['in','surface']],output:null}};
export const LIBRARY=[
 {id:'urban/asphalt',name:'Weathered asphalt',path:'Urban/Roads',kind:'urban',params:{kind:'asphalt',paint:'#626860',roughness:.92,wear:.35,seed:'URBAN-01'}},{id:'urban/paving',name:'Mineral paving',path:'Urban/Paving',kind:'urban',params:{kind:'paving',paint:'#a1a392',roughness:.84,wear:.35,seed:'URBAN-01'}},
 ...Object.entries(BUILDING_PROFILES).map(([profile,p])=>({id:'building/'+profile,name:p.label,path:'Buildings/'+(p.metal?'Metals':'Cladding'),kind:'building',params:{profile,zone:0,recipe:buildingMaterialPreset('inhabited')}})),
 ...Object.entries(PRESETS).map(([id,p])=>({id:'hull/'+id,name:p.name,path:'Spacecraft/'+(id==='alloy'?'Structural metals':'Coatings'),kind:'hull',params:{recipe:hullRecipe({preset:id})}})),
 ...[['moss','Moss / fibres'],['lichen','Lichen / crust'],['snow','Snow / firn'],['dust','Fine dust']].map(([id,name])=>({id:'growth/'+id,name,path:'Nature/Procedural',kind:'growth',params:{kind:id,seed:17,roughness:.85,relief:1,color:{moss:'#52753c',lichen:'#a5ac70',snow:'#e9f0f1',dust:'#a29473'}[id]}})),
 ...[['rock','Dry boulder','rock_boulder_dry'],['sand','Sandy gravel','sandy_gravel'],['mud','Cracked mud','mud_cracked_dry_03']].map(([id,name,base])=>({id:'scan/'+id,name,path:'Terrain/Existing scans',kind:'scan',params:{id,base},source:'Existing Poly Haven scan'}))
];
const clean=value=>JSON.parse(JSON.stringify(value));
export function node(kind,id,position={x:0,y:0},params={}){const defaults={noise:{seed:17,scale:8,coverage:.5,softness:.15,invert:false},blend:{amount:.6,heightBlend:.35,mode:'noise'},finish:{tint:'#ffffff',roughness:1,normalStrength:1},weather:{wear:.3,grime:.35,streaks:.4,oxidation:.25,deposits:.2,rain:.35,dust:.2,wetness:0,biology:.08}};return{id,kind,position,params:clean({...defaults[kind],...params})};}
export function graphFromMaterial(entry=LIBRARY[0]){let p=clean(entry.params);if(entry.kind==='building'&&!p.preserve){p.recipe=buildingMaterialRecipe(p.recipe);p.recipe.zones[p.zone].profile=p.profile;p.recipe.zones[p.zone].color=BUILDING_PROFILES[p.profile].color;p.recipe.zones[p.zone].roughness=BUILDING_PROFILES[p.profile].roughness;}
 return{schema:GRAPH_SCHEMA,id:entry.id,name:entry.name,folder:entry.path,revision:0,nodes:[node(entry.kind,'source',{x:0,y:90},p),node('output','output',{x:330,y:90})],edges:[{id:'source-output',source:'source',target:'output',targetHandle:'in'}]};}
export function validateGraph(input){
 if(!input||input.schema!==GRAPH_SCHEMA||!Array.isArray(input.nodes)||input.nodes.length<2||input.nodes.length>48||!Array.isArray(input.edges)||input.edges.length>96)throw Error('Invalid material graph');const g=clean(input),ids=new Set();
 for(const n of g.nodes){if(!n||typeof n.id!=='string'||n.id.length>100||ids.has(n.id)||!NODE_TYPES[n.kind])throw Error('Invalid or duplicate material node');ids.add(n.id);if(!n.params||typeof n.params!=='object'||!Number.isFinite(n.position?.x)||!Number.isFinite(n.position?.y))throw Error('Invalid node parameters');}
 for(const n of g.nodes){const p=n.params,num=(k,d,a=0,b=1)=>p[k]=Number.isFinite(Number(p[k]))?Math.max(a,Math.min(b,Number(p[k]))):d;if(['noise','growth','blend','weather'].includes(n.kind))num('seed',17,0,4294967295);if(n.kind==='buildingStage'){if(!BUILDING_STAGES.some(s=>s.id===p.stage))throw Error('Unknown building stage');const spec=BUILDING_STAGES.find(s=>s.id===p.stage);p.values=p.values||{};for(const k of Object.keys(p.values))if(!spec.keys.includes(k))delete p.values[k];for(const k of spec.keys){if(k==='color'){if(!/^#[\da-f]{6}$/i.test(p.values[k]||''))throw Error('Invalid coating color');}else{const v=Number(p.values[k]);if(!Number.isFinite(v))throw Error('Invalid building stage value');p.values[k]=Math.max(k.startsWith('panels')?1:0,Math.min(k.startsWith('panels')?4:k==='relief'?2:1,v));if(k.startsWith('panels'))p.values[k]=Math.round(p.values[k]);}}}if(n.kind==='building'){p.recipe=buildingMaterialRecipe(p.recipe);p.zone=Math.round(Math.max(0,Math.min(7,Number(p.zone)||0)));}if(n.kind==='hull')p.recipe=hullRecipe(p.recipe);if(n.kind==='bitmap'){num('heightScale',.02,0,.024);if(!p.images||typeof p.images!=='object'||!p.images.color)throw Error('A bitmap material needs a base color map');}if(p.images)for(const [key,url]of Object.entries(p.images))if(!['color','normal','roughness','metallic','ao','height','mask'].includes(key)||typeof url!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(url)||url.length>18e6)throw Error('Invalid embedded map');if(n.kind==='growth'){if(!['moss','lichen','snow','dust'].includes(p.kind))p.kind='moss';if(!/^#[\da-f]{6}$/i.test(p.color||''))p.color='#52753c';num('roughness',.85,.12,.98);num('relief',1,0,2);}if(n.kind==='noise'){num('scale',8,.25,64);num('coverage',.5);num('softness',.15,.01,.5);p.invert=!!p.invert;}if(n.kind==='blend'){num('amount',.6);num('heightBlend',.35);if(!['noise','uniform','cavity','height','upward'].includes(p.mode))p.mode='noise';}if(n.kind==='finish'){num('roughness',1,.1,2);num('normalStrength',1,0,3);if(!/^#[\da-f]{6}$/i.test(p.tint||''))p.tint='#ffffff';}if(n.kind==='weather')for(const k of ['wear','grime','streaks','oxidation','deposits','rain','dust','wetness','biology'])num(k,.2);if(n.kind==='urban'){p.kind=p.kind==='paving'?'paving':'asphalt';p.paint=/^#[\da-f]{6}$/i.test(p.paint||'')?p.paint:'#626860';num('roughness',.9,.12,.98);num('wear',.35);p.seed=String(p.seed||'URBAN-01').slice(0,100);}if(n.kind==='scan'&&!['rock','sand','mud'].includes(p.id))throw Error('Unknown scan');}
 if(g.nodes.filter(n=>n.kind==='output').length!==1)throw Error('A graph needs exactly one PBR output');const occupied=new Set();for(const e of g.edges){const a=g.nodes.find(n=>n.id===e.source),b=g.nodes.find(n=>n.id===e.target),port=NODE_TYPES[b?.kind]?.inputs.find(([id])=>id===e.targetHandle);if(!a||!b||!port||NODE_TYPES[a.kind].output!==port[1]||a.id===b.id)throw Error('Connect compatible surface or mask ports');const key=b.id+':'+port[0];if(occupied.has(key))throw Error('Each input accepts one connection');occupied.add(key);}
 const visiting=new Set(),visited=new Set();function visit(id){if(visiting.has(id))throw Error('Material graphs cannot contain cycles');if(visited.has(id))return;visiting.add(id);for(const e of g.edges.filter(e=>e.target===id))visit(e.source);visiting.delete(id);visited.add(id);}for(const n of g.nodes)visit(n.id);
 g.name=String(g.name||'Untitled material').slice(0,100);g.folder=String(g.folder||'My materials').slice(0,120);g.id=String(g.id||'custom').slice(0,160);return g;
}
export function connectionAllowed(g,c){try{validateGraph({...g,edges:[...g.edges.filter(e=>!(e.target===c.target&&e.targetHandle===c.targetHandle)),{...c,id:'candidate'}]});return true;}catch{return false;}}
export function compileGraph(input){const graph=validateGraph(input),lookup=new Map(graph.nodes.map(n=>[n.id,n])),seen=new Map();function build(id){if(seen.has(id))return seen.get(id);const n=lookup.get(id),inputs={};for(const [port,type]of NODE_TYPES[n.kind].inputs){const edge=graph.edges.find(e=>e.target===id&&e.targetHandle===port);if(!edge){if(n.kind==='blend'&&port==='mask')continue;throw Error(`${NODE_TYPES[n.kind].label}: connect ${port}`);}inputs[port]=build(edge.source);}const result={id:n.id,kind:n.kind,params:n.params,inputs};seen.set(id,result);return result;}const root=build(graph.nodes.find(n=>n.kind==='output').id).inputs.in;return{graph,root,nodes:[...seen.values()],signature:graphSignature({...graph,nodes:graph.nodes.filter(n=>seen.has(n.id)),edges:graph.edges.filter(e=>seen.has(e.source)&&seen.has(e.target))})};}
export function graphSignature(graph){const ordered={nodes:graph.nodes.map(n=>({id:n.id,kind:n.kind,params:n.params})).sort((a,b)=>a.id.localeCompare(b.id)),edges:graph.edges.map(e=>({source:e.source,target:e.target,port:e.targetHandle})).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))};let h=2166136261;for(const c of JSON.stringify(ordered)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return(h>>>0).toString(16);}
export function optimizedBuilding(program){const root=program.root;if(!root)return null;if(root.params.enabled===false&&root.inputs?.[root.kind==='blend'?'base':'in'])return optimizedBuilding({root:root.inputs[root.kind==='blend'?'base':'in']});if(root.kind==='building')return{recipe:buildingMaterialRecipe(root.params.recipe),zone:root.params.zone||0};if(['buildingStage','weather'].includes(root.kind)){const source=optimizedBuilding({root:root.inputs.in});if(!source)return null;const r=buildingMaterialRecipe(source.recipe),z=r.zones[source.zone];if(root.kind==='buildingStage'){for(const [k,v]of Object.entries(root.params.values))if(['rain','dust','wetness','biology'].includes(k))r.weather[k]=v;else z[k]=v;}else{for(const k of ['wear','grime','streaks','oxidation','deposits'])if(root.params[k]!==undefined)z[k]=root.params[k];for(const k of ['rain','dust','wetness','biology'])if(root.params[k]!==undefined)r.weather[k]=root.params[k];}return{recipe:buildingMaterialRecipe(r),zone:source.zone};}return null;}
export const BUILDING_STAGES=[
 {id:'structure',label:'Panel structure',keys:['panelsX','panelsY','grain','relief']},
 {id:'coating',label:'Coating & finish',keys:['color','roughness']},
 {id:'damage',label:'Chips & oxidation',keys:['wear','chips','oxidation']},
 {id:'grime',label:'Joint dirt',keys:['grime']},
 {id:'runoff',label:'Rain streaks',keys:['streaks','rain']},
 {id:'deposition',label:'Deposits & wetness',keys:['deposits','dust','wetness','biology']}
];
export function expandBuilding(input,id){const g=validateGraph(input),source=g.nodes.find(n=>n.id===id);if(source?.kind!=='building')throw Error('Select a compact building generator');if(g.nodes.length+6>48)throw Error('Expansion needs six free node slots');const original=buildingMaterialRecipe(source.params.recipe),zone=source.params.zone||0,z=original.zones[zone],base=buildingMaterialRecipe(original),bz=base.zones[zone];Object.assign(bz,{color:'#818782',roughness:.78,panelsX:1,panelsY:1,grain:0,relief:0,wear:0,chips:0,grime:0,streaks:0,oxidation:0,deposits:0});base.weather={rain:0,dust:0,wetness:0,biology:0};source.params.recipe=base;source.label='Substrate / '+bz.profile;const stages=BUILDING_STAGES.map((spec,i)=>{let next=id+'-'+spec.id;while(g.nodes.some(n=>n.id===next))next+='x';return{...node('buildingStage',next,{x:source.position.x+([1,2,2,1,0,0][i])*290,y:source.position.y+([0,0,1,1,1,2][i])*350},{stage:spec.id,values:Object.fromEntries(spec.keys.map(k=>[k,k in original.weather?original.weather[k]:z[k]]))}),label:spec.label};});for(const edge of g.edges)if(edge.source===id)edge.source=stages.at(-1).id;let previous=id;for(const stage of stages){g.nodes.push(stage);g.edges.push({id:previous+'-'+stage.id,source:previous,target:stage.id,targetHandle:'in'});previous=stage.id;}for(const n of g.nodes)if(n.kind==='output')n.position={x:stages.at(-1).position.x+300,y:stages.at(-1).position.y};return validateGraph(g);}
export function graphAtNode(input,id){const g=validateGraph(input),target=g.nodes.find(n=>n.id===id);if(!target)throw Error('Unknown node');if(target.kind==='output')return g;if(NODE_TYPES[target.kind].output==='mask')return null;const out=g.nodes.find(n=>n.kind==='output');g.edges=g.edges.filter(e=>e.target!==out.id);g.edges.push({id:'inspect-output',source:id,target:out.id,targetHandle:'in'});return g;}
export function nodeFingerprint(n){const inputs=Object.fromEntries(Object.entries(n.inputs||{}).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>[k,nodeFingerprint(v)]));let h=2166136261;for(const c of JSON.stringify([n.kind,n.params,inputs])){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return(h>>>0).toString(16);}
export function moveLayer(input,id,direction){const g=validateGraph(input),primary=n=>n.kind==='blend'?'base':'in',movable=n=>['buildingStage','blend','weather','finish'].includes(n?.kind),a=g.nodes.find(n=>n.id===id);if(!movable(a))return g;const incoming=n=>g.edges.find(e=>e.target===n.id&&e.targetHandle===primary(n));let lower,upper;if(direction<0){upper=a;lower=g.nodes.find(n=>n.id===incoming(a)?.source);}else{lower=a;const edge=g.edges.find(e=>e.source===a.id&&movable(g.nodes.find(n=>n.id===e.target))&&e.targetHandle===primary(g.nodes.find(n=>n.id===e.target)));upper=g.nodes.find(n=>n.id===edge?.target);}if(!movable(lower)||!movable(upper))return g;const before=incoming(lower),between=incoming(upper);if(!before||between?.source!==lower.id)return g;const after=g.edges.filter(e=>e.source===upper.id);before.target=upper.id;before.targetHandle=primary(upper);between.source=upper.id;between.target=lower.id;between.targetHandle=primary(lower);for(const e of after)e.source=lower.id;const pos=lower.position;lower.position=upper.position;upper.position=pos;validateGraph(g);compileGraph(g);return g;}
export function importRecipe(value){if(value.schema===GRAPH_SCHEMA)return validateGraph(value);if(value.schema==='aether.building-material/1')return graphFromMaterial({id:'custom/building',name:'Imported building finish',path:'My materials/Buildings',kind:'building',params:{profile:value.zones[0].profile,preserve:true,zone:0,recipe:buildingMaterialRecipe(value)}});if(value.schema==='aether-hull-material')return graphFromMaterial({id:'custom/hull',name:'Imported hull finish',path:'My materials/Spacecraft',kind:'hull',params:{recipe:hullRecipe(value.recipe),images:value.images||{}}});if([1,2].includes(value.version)&&Array.isArray(value.layers)){const nodes=[],edges=[];value.layers.forEach((l,i)=>{const entry=LIBRARY.find(m=>m.id==='scan/'+l.material||m.id==='growth/'+l.material);if(!entry)throw Error('Unknown legacy material');nodes.push(node(entry.kind,'layer'+i,{x:0,y:i*180},entry.params));if(i){nodes.push(node('noise','mask'+i,{x:240,y:i*190},{seed:l.mask?.seed||17,scale:l.mask?.scale||8,coverage:l.mask?.coverage||.5,softness:l.mask?.softness||.15,invert:l.mask?.invert||false}));nodes.push(node('blend','blend'+i,{x:500+i*230,y:120},{amount:l.weight/100,heightBlend:value.heightBlend||0,mode:l.mask?.type==='upward'?'height':l.mask?.type||'noise'}));edges.push({id:'base'+i,source:i===1?'layer0':'blend'+(i-1),target:'blend'+i,targetHandle:'base'},{id:'layer'+i,source:'layer'+i,target:'blend'+i,targetHandle:'layer'},{id:'mask'+i,source:'mask'+i,target:'blend'+i,targetHandle:'mask'});}});nodes.push(node('finish','finish',{x:1100,y:100},{tint:value.tint||'#ffffff',roughness:value.roughness||1,normalStrength:value.normalStrength||1}),node('output','output',{x:1400,y:100}));edges.push({id:'final',source:'blend2',target:'finish',targetHandle:'in'},{id:'out',source:'finish',target:'output',targetHandle:'in'});return validateGraph({schema:GRAPH_SCHEMA,id:'custom/legacy',name:value.name,folder:'My materials/Terrain',nodes,edges});}throw Error('Choose a material graph, building, hull or terrain recipe');}

export const STARTERS=[['moss','Moss on boulder','rock','moss'],['snow','Snow-capped rock','rock','snow'],['soil','Dust over cracked mud','mud','dust']].map(([id,name,base,layer])=>{const graph=importRecipe({version:2,name,layers:[{material:base,weight:100,mask:{type:'uniform',coverage:1}},{material:layer,weight:75,mask:{type:'noise',coverage:.6,scale:8,softness:.15,seed:17}},{material:'lichen',weight:15,mask:{type:'noise',coverage:.3,scale:16,softness:.15,seed:27}}],heightBlend:.35,normalStrength:1,roughness:1,tint:'#ffffff'});graph.id='starter/'+id;graph.folder='Composites/Terrain';return{id:graph.id,name,path:graph.folder,kind:'output',source:'Starter graph',graph};});
